#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections;using NUnit.Framework;using UnityEngine;using UnityEngine.TestTools;using UnityEditor;using UnityEngine.Video;using UnityEngine.InputSystem;
namespace HorrorGame.Tests {
 [Category("TutorialCards")]public sealed class TutorialCardPlayTests {
  BeforeDemolitionChapterFixture f;TutorialCardSystem s;TutorialCardCatalog catalog;FlashlightController lamp;float oldVolume;
  static int OwnedTextures()=>Resources.FindObjectsOfTypeAll<RenderTexture>().Count(t=>t.name=="Inspection item"||t.name=="Tutorial video (temporary)");
  [UnitySetUp]public IEnumerator Setup(){f=new BeforeDemolitionChapterFixture("tutorial.fixture",new[]{new StoryMilestoneDefinition{id="tutorial.event"}},true);oldVolume=AudioListener.volume;f.root.GetComponent<AudioManager>().enabled=true;catalog=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<TutorialCardCatalog>("Assets/HorrorGameplay/Data/TutorialCards/TutorialCardCatalog.asset"));catalog.cards=catalog.cards.Select(c=>UnityEngine.Object.Instantiate(c)).ToArray();s=f.root.AddComponent<TutorialCardSystem>();s.game=f.game;s.catalog=catalog;lamp=f.player.gameObject.AddComponent<FlashlightController>();lamp.lamp=f.Child("Lamp").AddComponent<Light>();lamp.view=f.camera;var input=f.root.AddComponent<InputReader>();input.asset=AssetDatabase.LoadAssetAtPath<InputActionAsset>("Assets/HorrorGameplay/Input/HorrorInput.inputactions");f.game.input=input;if(!UnityEngine.EventSystems.EventSystem.current){var es=f.Child("EventSystem");es.AddComponent<UnityEngine.EventSystems.EventSystem>();es.AddComponent<UnityEngine.InputSystem.UI.InputSystemUIInputModule>();}TutorialPreferences.Set(TutorialMode.Full);yield return f.Activate();s.SetMode(TutorialMode.Full);}
  [UnityTearDown]public IEnumerator Cleanup(){if(s)s.Close();if(f!=null)yield return f.Dispose();if(catalog){foreach(var c in catalog.cards)if(c)UnityEngine.Object.Destroy(c);UnityEngine.Object.Destroy(catalog);}AudioListener.volume=oldVolume;yield return null;}
  void Ready(string id){Assert.That(s.Discover(id),Is.True);foreach(var p in s.State.pending)p.remaining=0;}
  IEnumerator Control(){yield return BeforeDemolitionChapterFixture.Until(()=>f.game.CanControl&&!f.director.SequencePlaying,"Control available");}
  [UnityTest]public IEnumerator OpensOncePausesBatteryClockNarrativeAndRestores(){Ready("lockpick");float battery=lamp.BatterySeconds,clock=GameClock.Instance.State.elapsed;s.Tick(.1f);Assert.That(s.Current.id,Is.EqualTo("lockpick"));Assert.That(f.game.State,Is.EqualTo(GameState.Tutorial));Assert.That(Time.timeScale,Is.Zero);Assert.That(f.game.CanControl,Is.False);Assert.That(f.director.Signal("tutorial.event"),Is.False);yield return new WaitForSecondsRealtime(.25f);Assert.That(lamp.BatterySeconds,Is.EqualTo(battery).Within(.001f));Assert.That(GameClock.Instance.State.elapsed,Is.EqualTo(clock).Within(.001f));Assert.That(AudioManager.Instance.TutorialDuckLevel,Is.LessThan(1));s.View.understood.onClick.Invoke();yield return Control();Assert.That(Time.timeScale,Is.EqualTo(1));Assert.That(s.Discover("lockpick"),Is.False);s.Tick(1);Assert.That(s.IsOpen,Is.False);yield return new WaitForSeconds(.1f);Assert.That(lamp.BatterySeconds,Is.LessThan(battery));}
  [UnityTest]public IEnumerator QueueWaitsThroughCutsceneInspectionAndPause(){s.enabled=false;Ready("lockpick");f.game.DisableControl();s.Tick(1);Assert.That(s.IsOpen,Is.False);f.game.EnableControl();yield return Control();Assert.That(f.game.BeginInspection(),Is.True);s.Tick(1);Assert.That(s.IsOpen,Is.False);f.game.EndInspection();yield return Control();f.game.Pause();s.Tick(1);Assert.That(s.IsOpen,Is.False);Assert.That(s.State.pending.Count,Is.EqualTo(1));f.game.Resume();yield return Control();s.Tick(.1f);Assert.That(s.IsOpen,Is.True);s.Close();}
  [UnityTest]public IEnumerator DisabledModeKeepsHelpLimitedToDiscoveredItems(){s.SetMode(TutorialMode.Off);Ready("lockpick");s.Tick(1);Assert.That(s.IsOpen,Is.False);Assert.That(s.HelpCards.Select(c=>c.id),Is.EqualTo(new[]{"lockpick"}));f.game.Pause();Assert.That(s.ShowHelp(),Is.True);Assert.That(s.View.helpButtons.Count,Is.EqualTo(1));s.View.helpButtons[0].onClick.Invoke();Assert.That(s.Current.id,Is.EqualTo("lockpick"));s.Close();Assert.That(s.View.HelpVisible,Is.True);Assert.That(f.game.State,Is.EqualTo(GameState.Paused));s.CloseHelp();Assert.That(s.IsVisible,Is.False);yield return null;}
  [UnityTest]public IEnumerator LegacyOwnershipIsAcknowledgedAndOnlyNewGainsQueue(){s.SetMode(TutorialMode.Off);f.inventory.Add(new InventoryItem{id=LockpickSystem.ItemId});s.Restore(null);Assert.That(s.State.seen,Does.Contain("lockpick"));Assert.That(s.State.pending,Is.Empty);s.SetMode(TutorialMode.Full);s.Tick(1);Assert.That(s.IsOpen,Is.False);s.Discover("whistle");Assert.That(s.BlocksWhistle,Is.True);var capture=s.Capture();s.Restore(capture);Assert.That(s.State.pending.Single().id,Is.EqualTo("whistle"));foreach(var p in s.State.pending)p.remaining=0;s.Tick(.1f);Assert.That(s.IsOpen,Is.True);Assert.That(s.BlocksWhistle,Is.False);s.Close();yield return Control();}
  [UnityTest]public IEnumerator TextOnlyDoesNotAllocateVideoAndFallbackClosesCleanly(){int textures=OwnedTextures(),players=Resources.FindObjectsOfTypeAll<VideoPlayer>().Length;s.SetMode(TutorialMode.TextOnly);Ready("whistle");s.Tick(.1f);Assert.That(s.View.media.VideoAllocated||s.View.media.TextureAllocated,Is.False);Assert.That(s.View.mediaRect.gameObject.activeSelf,Is.False);s.Close();yield return Control();s.State.seen.Remove("whistle");s.SetMode(TutorialMode.Full);Assert.That(s.Open("whistle",false),Is.True);Assert.That(s.View.media.Prepared,Is.True);Assert.That(s.View.media.image.texture,Is.Not.Null);s.View.media.Fallback();Assert.That(s.View.media.Failed,Is.True);s.Close();yield return null;yield return null;Assert.That(Resources.FindObjectsOfTypeAll<VideoPlayer>().Length,Is.EqualTo(players));Assert.That(OwnedTextures(),Is.EqualTo(textures));}
  [UnityTest]public IEnumerator InspectionRendererIsReusedAndReleased(){int textures=OwnedTextures();Ready("flashlight");s.Tick(.1f);Assert.That(s.View.media.Prepared,Is.True);Assert.That(s.View.media.image.texture is RenderTexture,Is.True);Assert.That(s.View.media.GetComponent<InspectionCameraController>(),Is.Not.Null);yield return null;yield return null;var target=(RenderTexture)s.View.media.image.texture;var previous=RenderTexture.active;var pixels=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);try{RenderTexture.active=target;pixels.ReadPixels(new Rect(0,0,target.width,target.height),0,0);pixels.Apply();Assert.That(pixels.GetPixels32().Count(p=>p.r>25||p.g>25||p.b>25),Is.GreaterThan(500),"Actual flashlight pixels, not an empty render target");Directory.CreateDirectory("C:/Users/ruhtra/Documents/Codex/2026-09-29/oi/outputs/TutorialCards20261101");File.WriteAllBytes("C:/Users/ruhtra/Documents/Codex/2026-09-29/oi/outputs/TutorialCards20261101/flashlight-preview.png",pixels.EncodeToPNG());}finally{RenderTexture.active=previous;UnityEngine.Object.Destroy(pixels);}s.View.replay.onClick.Invoke();yield return null;s.Close();yield return null;yield return null;Assert.That(OwnedTextures(),Is.EqualTo(textures));}
  [UnityTest]public IEnumerator LiveBindingChangesRefreshTheOpenCard(){Ready("lockpick");s.Tick(.1f);var action=f.game.input.Actions.FindAction("Gameplay/Equip3");int index=action.bindings.ToList().FindIndex(b=>(b.effectivePath??"").Contains("<Keyboard>/3"));action.ApplyBindingOverride(index,"<Keyboard>/g");yield return null;Assert.That(s.View.GetComponentsInChildren<TMPro.TMP_Text>(true).Any(t=>t.name=="Tecla atual"&&t.text.ToUpperInvariant()=="G"),Is.True);}
  [UnityTest]public IEnumerator CardsHaveNoDisableButton(){Ready("lockpick");s.Tick(.1f);Assert.That(s.View.GetComponentsInChildren<UnityEngine.UI.Button>(true).Any(b=>b.name=="Desligar dicas"||b.name=="Confirmar desligar"),Is.False);Assert.That(s.View.GetComponentsInChildren<TMPro.TMP_Text>(true).Any(t=>t.text.Contains("Não mostrar mais")),Is.False);s.View.understood.onClick.Invoke();yield return Control();Assert.That(TutorialPreferences.Mode,Is.EqualTo(TutorialMode.Full));}

  [UnityTest]public IEnumerator ExplicitEnabledPreferenceIsNotDisabledByOlderCheckpoint(){Ready("lockpick");var saved=s.Capture();saved.mode=TutorialMode.Off;s.Restore(saved);Assert.That(TutorialPreferences.Mode,Is.EqualTo(TutorialMode.Full),"The current enabled option must survive loading an older disabled checkpoint");foreach(var p in s.State.pending)p.remaining=0;s.Tick(.1f);Assert.That(s.Current.id,Is.EqualTo("lockpick"));s.Close();yield return Control();}
  [UnityTest]public IEnumerator SoundCaptionsDoNotStarveTheQueueButSpeechStillBlocks(){var hud=f.Child("Caption gate").AddComponent<GameHUD>();hud.enabled=false;hud.subtitle=f.Label("Subtitle",hud.transform);hud.subtitleGroup=hud.subtitle.gameObject.AddComponent<CanvasGroup>();hud.subtitleGroup.alpha=1;f.game.hud=hud;hud.subtitle.text="[Passos]";Assert.That(s.SafeToShow,Is.True,"Recurring sound captions must not hold the item explanation forever");hud.subtitle.text="João: Já fiz isso mais vezes do que devia.";Assert.That(s.SafeToShow,Is.False);hud.subtitle.text="[clique]\nJoão: Abriu.";Assert.That(s.SafeToShow,Is.False);yield return null;}
  [UnityTest,Timeout(45000)]public IEnumerator RealH264VideoPreparesAndAdvancesAtTimeScaleZeroWithoutLeaks(){var clip=AssetDatabase.LoadAssetAtPath<VideoClip>("Assets/HorrorGameplay/Tests/Fixtures/Tutorial/codec_probe.mp4");Assert.That(clip,Is.Not.Null);catalog.Find("whistle").video=clip;int textures=OwnedTextures(),players=Resources.FindObjectsOfTypeAll<VideoPlayer>().Length;Ready("whistle");s.Tick(.1f);yield return BeforeDemolitionChapterFixture.Until(()=>s.View.media.Prepared,"Prepare first video frame",15);Assert.That(s.View.media.Failed,Is.False);var player=s.View.media.GetComponent<VideoPlayer>();Assert.That(player.isPrepared,Is.True);long frame=player.frame;yield return new WaitForSecondsRealtime(.25f);Assert.That(Time.timeScale,Is.Zero);Assert.That(player.frame,Is.GreaterThan(frame));Directory.CreateDirectory("C:/Users/ruhtra/Documents/Codex/2026-09-29/oi/outputs/TutorialCards20261101");File.WriteAllText("C:/Users/ruhtra/Documents/Codex/2026-09-29/oi/outputs/TutorialCards20261101/video-prepare.json","{\"codec\":\"H.264 MP4 yuv420p\",\"prepareMilliseconds\":"+s.View.media.PrepareMilliseconds.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"atTimeScaleZero\":true,\"technicalClipOnly\":true}");s.View.media.Fallback();Assert.That(s.View.media.Failed,Is.True);s.View.replay.onClick.Invoke();yield return BeforeDemolitionChapterFixture.Until(()=>s.View.media.Prepared&&!s.View.media.Failed,"Replay retries video after fallback",15);s.Close();yield return null;yield return null;Assert.That(Resources.FindObjectsOfTypeAll<VideoPlayer>().Length,Is.EqualTo(players));Assert.That(OwnedTextures(),Is.EqualTo(textures));}
 }
}
